def eom(y,m):
    return date(y,m,calendar.monthrange(y,m)[1]).isoformat()

rows=[]
for code, series in data.items():
    series = sorted(series, key=lambda x:x[0])
    for i in range(1,len(series)):
        prev_c = series[i-1][1]
        cur_d, cur_c = series[i]
        y=int(cur_d[:4]); mo=int(cur_d[4:6])
        if y==2026 and 1<=mo<=6:
            rows.append((code, eom(y,mo), cur_c/prev_c - 1))

with open(OUT,"a",newline="") as f:
    w=csv.writer(f)
    for r in rows:
        w.writerow(r)
print("batch rows written:", len(rows))
